import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONT LOADER
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type FallingFilesBoxProps = Record<string, any>;

// ------------------------------------------------------------------
// SUB-COMPONENTS
// ------------------------------------------------------------------

const FileIcon: React.FC<{
  color: string;
  size: number;
  label?: string;
  opacity: number;
}> = ({ color, size, label = "MP4", opacity }) => {
  return (
    <div
      style={{
        width: size,
        height: size * 1.3,
        backgroundColor: color,
        borderRadius: size * 0.1,
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        boxShadow: "0 4px 6px rgba(0,0,0,0.1)",
        opacity,
      }}
    >
      {/* Folded Corner */}
      <div
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          width: size * 0.3,
          height: size * 0.3,
          background: "rgba(0,0,0,0.1)",
          borderBottomLeftRadius: size * 0.1,
          borderTopRightRadius: size * 0.1,
        }}
      />
      <span
        style={{
          fontFamily: "Roboto Mono",
          fontWeight: 700,
          fontSize: size * 0.25,
          color: "rgba(0,0,0,0.6)",
        }}
      >
        {label}
      </span>
    </div>
  );
};

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const FallingFilesBox: React.FC<FallingFilesBoxProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 8,
  fileCount = 6,
  dropInterval = 12,
  boxColor = "#A07656", // Cardboard brown default
  iconColor = "#ffffff",
  boxSize = 250,
}) => {
  useFontLoader(["Inter", "Roboto Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // ----------------------------------------------------------------
  // CALCULATIONS
  // ----------------------------------------------------------------
  
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Box Dimensions
  const boxWidth = boxSize;
  const boxHeight = boxSize * 0.6; // Shorter height for the box itself
  const boxDepth = boxSize; 
  
  // Center Position
  const centerX = width / 2;
  const centerY = height / 2 + boxHeight / 2; // Shift down slightly

  // Generate Files Data
  const files = useMemo(() => {
    return Array.from({ length: fileCount }).map((_, i) => ({
      id: i,
      startFrame: 15 + i * dropInterval, // Initial delay + stagger
      xOffset: (Math.random() - 0.5) * (boxWidth * 0.6), // Randomize landing spot X
      zOffset: (Math.random() - 0.5) * (boxDepth * 0.6), // Randomize landing spot Z (simulated)
      rotation: (Math.random() - 0.5) * 45, // Random rotation
    }));
  }, [fileCount, dropInterval, boxWidth, boxDepth]);

  // Calculate Box Bounce (Squash & Stretch)
  // We sum up spring impulses from each file impact
  const boxBounceScale = useMemo(() => {
    let scaleY = 1;
    let scaleX = 1;

    files.forEach((file) => {
      // Approximate frame where file hits the bottom
      // Based on the spring config used below for fileDrop
      // A typical spring with these settings settles around 15-20 frames
      const impactFrame = file.startFrame + 12; 
      
      if (frame >= impactFrame) {
        const bounce = spring({
          frame: frame - impactFrame,
          fps,
          config: { damping: 5, stiffness: 200, mass: 0.5 },
        });
        
        // Convert the 0->1 spring to an impulse curve (0 -> 1 -> 0)
        // We use interpolation to shape the spring curve into a "bump"
        const impulse = interpolate(bounce, [0, 0.3, 1], [0, 0.08, 0], {
            extrapolateRight: "clamp"
        });

        scaleY -= impulse; // Squash down
        scaleX += impulse * 0.5; // Stretch out
      }
    });

    return { x: scaleX, y: scaleY };
  }, [files, frame, fps]);


  // Box Entrance Animation
  const boxEntrance = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 80 },
  });
  
  // ----------------------------------------------------------------
  // RENDER HELPERS
  // ----------------------------------------------------------------
  
  // Darken colors for depth
  const darkerBoxColor = `${boxColor}CC`; // 80% opacity
  const darkestBoxColor = `${boxColor}`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        perspective: "1200px", // Essential for 3D
        overflow: "hidden",
      }}
    >
      {/* 3D Scene Container */}
      <div
        style={{
          width: "100%",
          height: "100%",
          transformStyle: "preserve-3d",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          // Tilt the camera slightly to look into the box
          transform: `rotateX(-25deg) translateY(${interpolate(boxEntrance, [0, 1], [200, 0])}px) scale(${boxEntrance})`,
        }}
      >
        {/* THE BOX CONTAINER */}
        <div
          style={{
            position: "relative",
            width: boxWidth,
            height: boxHeight,
            transformStyle: "preserve-3d",
            transform: `scaleX(${boxBounceScale.x}) scaleY(${boxBounceScale.y})`,
          }}
        >
            {/* BOX BACK FACE */}
            <div
                style={{
                    position: "absolute",
                    width: boxWidth,
                    height: boxHeight,
                    backgroundColor: darkestBoxColor,
                    transform: `translateZ(-${boxDepth / 2}px)`,
                    backfaceVisibility: "hidden",
                    // Gradient for inner shadow
                    backgroundImage: "linear-gradient(to bottom, rgba(0,0,0,0.2), rgba(0,0,0,0))",
                    border: "2px solid rgba(255,255,255,0.1)",
                    borderRadius: 4
                }}
            />
            
            {/* BOX BOTTOM FACE */}
            <div
                style={{
                    position: "absolute",
                    width: boxWidth,
                    height: boxDepth,
                    backgroundColor: darkerBoxColor,
                    transform: `rotateX(90deg) translateZ(-${boxHeight / 2}px)`, // Adjust Z to align with bottom of sides
                    // Inner shadow gradient
                    backgroundImage: "radial-gradient(circle, rgba(0,0,0,0) 0%, rgba(0,0,0,0.3) 100%)",
                }}
            />

            {/* BOX LEFT FACE (Inner) */}
            <div
                style={{
                    position: "absolute",
                    width: boxDepth,
                    height: boxHeight,
                    backgroundColor: darkerBoxColor,
                    transform: `rotateY(90deg) translateZ(-${boxWidth / 2}px)`,
                    backgroundImage: "linear-gradient(to right, rgba(0,0,0,0.1), rgba(0,0,0,0))",
                    border: "2px solid rgba(255,255,255,0.1)",
                    borderRadius: 4
                }}
            />

            {/* BOX RIGHT FACE (Inner) */}
            <div
                style={{
                    position: "absolute",
                    width: boxDepth,
                    height: boxHeight,
                    backgroundColor: darkerBoxColor,
                    transform: `rotateY(-90deg) translateZ(-${boxWidth / 2}px)`,
                    backgroundImage: "linear-gradient(to left, rgba(0,0,0,0.1), rgba(0,0,0,0))",
                    border: "2px solid rgba(255,255,255,0.1)",
                    borderRadius: 4
                }}
            />

            {/* FALLING FILES LAYER 
                Placed here in DOM order so they are IN FRONT of Back/Bottom but BEHIND Front
            */}
            {files.map((file) => {
                const progress = spring({
                    frame: frame - file.startFrame,
                    fps,
                    config: { damping: 12, stiffness: 100, mass: 0.8 },
                });

                // Falling Math
                // Start high above (negative Y), land at random bottom offset
                // Box bottom is at local Y ~ boxHeight/2
                const dropDistance = 800;
                const startY = -dropDistance;
                const endY = boxHeight / 2 - 20; // Land inside near bottom
                
                const currentY = interpolate(progress, [0, 1], [startY, endY]);
                
                // Opacity fade in
                const opacity = interpolate(progress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });
                
                // Rotation wiggle while falling
                const fallRotation = interpolate(progress, [0, 1], [file.rotation * 2, file.rotation]);
                
                // Simulating Z-depth via Scale and actual TranslateZ
                // We want them inside the box, so Z should be between -depth/2 and +depth/2
                // We fake "falling into depth" slightly for visual flair
                const currentZ = file.zOffset;

                // Don't render if not started
                if (frame < file.startFrame) return null;

                return (
                    <div
                        key={file.id}
                        style={{
                            position: "absolute",
                            left: "50%",
                            top: "50%", // Centered in container
                            width: 0, height: 0, // Wrapper size
                            transformStyle: "preserve-3d",
                            transform: `
                                translateX(${file.xOffset}px) 
                                translateY(${currentY - boxHeight/2}px) 
                                translateZ(${currentZ}px)
                                rotateZ(${fallRotation}deg)
                                rotateX(${interpolate(progress, [0,1], [45, 10])}deg)
                            `,
                            zIndex: 10, // Logic z-index
                        }}
                    >
                        <div style={{ transform: "translate(-50%, -100%)" }}> {/* Pivot at bottom center */}
                            <FileIcon 
                                color={iconColor} 
                                size={boxWidth * 0.15} 
                                opacity={opacity} 
                            />
                        </div>
                    </div>
                );
            })}

            {/* BOX FRONT FACE 
                Must be last to cover the files
            */}
            <div
                style={{
                    position: "absolute",
                    width: boxWidth,
                    height: boxHeight,
                    backgroundColor: `${boxColor}99`, // Slightly transparent to see through?
                    // Actually, let's make it opaque but cut out or just solid to hide contents cleanly
                    // Request said "open box", usually implies we see inside.
                    // If we use transparent front, we see files through it.
                    // Let's stick to standard opaque sides for a clean look, front face creates the "pocket"
                    background: `linear-gradient(135deg, ${boxColor}, ${darkerBoxColor})`,
                    transform: `translateZ(${boxDepth / 2}px)`,
                    opacity: 0.95, // Glassy feel
                    border: "2px solid rgba(255,255,255,0.2)",
                    borderRadius: 4,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center"
                }}
            >
                 {/* Optional Box Label */}
                 <div style={{
                     color: "rgba(255,255,255,0.3)",
                     fontWeight: 900,
                     fontSize: boxWidth * 0.08, // Adjusted for longer text
                     letterSpacing: -1,
                     textAlign: "center",
                     lineHeight: 1.1,
                     padding: "0 10px"
                 }}>
                     DRAG AND DROP
                 </div>
            </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FallingFilesBox;